module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // Internal signals for the current and previous sensor states
    logic [2:0] s_reg;
    logic [2:0] s_prev;

    // Outputs
    logic       fr2_o;
    logic       fr1_o;
    logic       fr0_o;
    logic       dfr_o;

    // ------------------------------------------------------------
    // Register updates (synchronous reset, edge-sensitive on clk)
    // ------------------------------------------------------------
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            s_reg <= 3'b000;
            s_prev <= 3'b000;
        end else begin
            s_reg <= s;
            s_prev <= s_reg;   // previous state (last sensor change)
        end
    end

    // ------------------------------------------------------------
    // Combinational logic for output assignment
    // ------------------------------------------------------------
    always_comb begin
        // Default assignments (all outputs high = asserted, as per spec)
        fr2_o = 1'b1;
        fr1_o = 1'b1;
        fr0_o = 1'b1;
        dfr_o = 1'b1;

        // Determine the current water level zone and assert the proper
        // nominal flow inputs (fr0, fr1, fr2) and supplemental flow (dfr).

        // 1. Above s[2]  -> no sensors asserted, no nominal flow
        if (s == 3'b111) begin
            // None
        end
        // 2. Between s[2] and s[1]  -> s[0], s[1] asserted
        else if (s == 3'b110) begin
            fr0_o = 1'b1;   // fr0 asserted
            // fr1, fr2 remain default (1'b1) but fr2 is not required;
            // we keep them as per default (asserted) unless spec says otherwise.
            // The table says "fr0" only.
        end
        // 3. Between s[1] and s[0]  -> s[0] asserted
        else if (s == 3'b100) begin
            fr0_o = 1'b1;
            fr1_o = 1'b1;   // supplemental? table says fr0, fr1
            // dfr controlled later by level change detection
        end
        // 4. Below s[0]   -> no sensors asserted, max flow
        else if (s == 3'b000) begin
            fr0_o = 1'b1;
            fr1_o = 1'b1;
            fr2_o = 1'b1;
            dfr_o = 1'b1;   // supplemental open at max flow
        end
        // Cases with partial sensor assertions (should not happen with
        // exactly three sensors at 5‑inch intervals, but handle gracefully)
        else begin
            // If only s[2] is asserted (level exactly at highest sensor)
            if (s[2]) begin
                // treat as above s[2] -> no nominal flow
            end else if (s[1]) begin
                // between s[2] and s[1] but s[0] missing -> default
                fr0_o = 1'b1;
            end else if (s[0]) begin
                // between s[1] and s[0] but s[1] missing
                fr0_o = 1'b1;
                fr1_o = 1'b1;
            end
        end

        // --------------------------------------------------------
        // Supplemental flow valve (dfr) control
        // --------------------------------------------------------
        // If the sensor change indicates that the previous level was
        // lower than the current level, open the Supplemental flow valve.
        // "Lower than the current level" means the previous sensor state
        // represented a lower water level.  We detect this by checking
        // if any bit that is 1 in s is 0 in s_prev (i.e., level rose).
        if ((s & ~s_prev) != 3'b000) begin
            // Level rose -> open supplemental flow valve
            dfr_o = 1'b1;
        end else begin
            // Level did not rise (fell or stayed same) -> close dfr
            dfr_o = 1'b0;
        end
    end

    // ------------------------------------------------------------
    // Assign module outputs
    // ------------------------------------------------------------
    assign fr2 = fr2_o;
    assign fr1 = fr1_o;
    assign fr0 = fr0_o;
    assign dfr = dfr_o;

endmodule

