        if (d & s)
            next_state[1] = 1'b1;           // S -> S1 (explicit)

        // S11 transitions (not explicitly driven; defaults to unspecified per spec)

        // S110 transitions
        if (~d)
            next_state[0] = 1'b1;           // S110 -> S
        else
            next_state[4] = 1'b1;           // S110 -> B0

        // B0, B1, B2, B3 always advance one cycle
        if (b0)
            next_state[5] = 1'b1;           // B0 -> B1
        if (b1)
            next_state[6] = 1'b1;           // B1 -> B2
        if (b2)
            next_state[7] = 1'b1;           // B2 -> B3
        if (b3)
            next_state[8] = 1'b1;           // B3 -> Count

