        if (count) begin
            if (~done_counting)
                next_state[8] = 1'b1;      // Count -> Count
            else
                next_state[9] = 1'b1;      // Count -> Wait
        end

        // Wait transitions
        if (wait_n) begin
            if (~ack)
                next_state[9] = 1'b1;      // Wait -> Wait
            else
                next_state[0] = 1'b1;      // Wait -> S
        end
    end

    // ---------- Output logic (Moore machine) ----------
    // done: asserted when in Wait state
    assign done = wait_n;

    // counting: asserted when in Count state
    assign counting = count;

    // shift_ena: asserted in B0, B1, B2, B3 states
    assign shift_ena = b0 | b1 | b2 | b3;

endmodule

