module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [3:0] {
        WALK_LEFT,    // 0
        WALK_RIGHT,   // 1
        FALLING,      // 2
        DIGGING,      // 3
        SPLATTERED    // 4
    } state_t;

    // Sequential logic: state register
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALK_LEFT;
        end else begin
            // Priority: fall > dig > switch direction
            // 1. Splatter check: if falling > 20 cycles and ground rises
            if (state == FALLING && ground) begin
                if (fall_cycle_cnt > 20) begin
                    state <= SPLATTERED;
                end else begin
                    state <= WALK_LEFT;  // resume walking left on ground
                    fall_cycle_cnt <= 0;
                end
            end
            // 2. Dig check: only if on ground (not falling) and dig=1
            else if (state != FALLING && state != SPLATTERED && ground && dig) begin
                state <= DIGGING;
            end
            // 3. Direction switch: only if on ground and not digging
            else if (state != SPLATTERED && ground) begin
                if (bump_left || bump_right) begin
                    // If bumped on both sides, still switch
                    if (bump_left && bump_right) begin
                        // Toggle direction
                        if (state == WALK_LEFT)
                            state <= WALK_RIGHT;
                        else
                            state <= WALK_LEFT;
                    end else if (bump_left) begin
                        state <= WALK_RIGHT;
                    end else if (bump_right) begin
                        state <= WALK_LEFT;
                    end
                end
            end
            // 4. Fall: when ground=0 and not digging/splattered
            else if (state != SPLATTERED && !ground) begin
                state <= FALLING;
                fall_cycle_cnt <= fall_cycle_cnt + 1;
            end
            // 5. If already splattered, stay splattered
            else if (state == SPLATTERED) begin
                state <= SPLATTERED;
            end
            // 6. Default: stay in current state
            else begin
                state <= state;
            end
        end
    end

    // Falling cycle counter (max 20+1 to detect >20)
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            fall_cycle_cnt <= 0;
        end else begin
            if (state == FALLING && !ground) begin
                fall_cycle_cnt <= fall_cycle_cnt + 1;
            end else if (state == FALLING && ground) begin
                // Reset when hitting ground (whether splatter or resume)
                fall_cycle_cnt <= 0;
            end else begin
                fall_cycle_cnt <= 0;
            end
        end
    end

    // Output logic (Moore machine: outputs depend only on state)
    assign walk_left   = (state == WALK_LEFT)   ? 1'b1 : 1'b0;
    assign walk_right  = (state == WALK_RIGHT)  ? 1'b1 : 1'b0;
    assign aaah        = (state == FALLING)     ? 1'b1 : 1'b0;
    assign digging     = (state == DIGGING)     ? 1'b1 : 1'b0;

endmodule

