module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic [7:0] in,
    output logic [23:0] out_bytes,
    output logic done
);

    // FSM state encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        GET1   = 2'b01,
        GET2   = 2'b10,
        GET3   = 2'b11
    } state_t;

    logic [1:0] state, next_state;
    logic [1:0] byte_cnt;   // counts received bytes (1,2,3)
    logic [23:0] shift_reg; // holds the 3-byte message

    // -------------------------------------------------
    // FSM state register (synchronous reset)
    // -------------------------------------------------
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            byte_cnt  <= 0;
            shift_reg <= 0;
            done      <= 1'b0;
        end else begin
            state     <= next_state;
            byte_cnt  <= next_byte_cnt;
            shift_reg <= next_shift_reg;
            done      <= next_done;
        end
    end

    // -------------------------------------------------
    // Next-state / datapath logic (combinational)
    // -------------------------------------------------
    always_comb begin
        // Default assignments (keep values when not transitioning)
        next_state     = state;
        next_byte_cnt  = byte_cnt;
        next_shift_reg = shift_reg;
        next_done      = 1'b0;

        case (state)
            IDLE: begin
                if (in[3]) begin
                    // Found byte 1 of a message
                    next_state   = GET1;
                    next_byte_cnt = 1;
                    next_shift_reg = {24{1'b0}}; // clear shift register
                    // Load first byte into the top byte of shift_reg
                    next_shift_reg = {in, 16{1'b0}};
                end else begin
                    // Stay in IDLE, discard byte
                    next_state = IDLE;
                end
            end

            GET1: begin
                // Shift in second byte
                next_shift_reg = {shift_reg[23:8], in};
                next_byte_cnt  = 2;
                next_state     = GET2;
            end

            GET2: begin
                // Shift in third byte
                next_shift_reg = {shift_reg[23:8], in};
                next_byte_cnt  = 3;
                next_state     = GET3;
            end

            GET3: begin
                // All 3 bytes received – assert done next cycle
                next_done = 1'b1;
                // Keep shift_reg valid for out_bytes output
                next_state = IDLE; // reset for next message
                // byte_cnt will roll over; not critical after done
            end

            default: next_state = IDLE;
        endcase
    end

    // -------------------------------------------------
    // out_bytes assignment – valid whenever done is asserted
    // -------------------------------------------------
    // out_bytes is a logic port; we drive it from shift_reg.
    // The specification says: out_bytes[23:16] is the first byte,
    // out_bytes[15:8]  is the second, out_bytes[7:0]  is the third.
    // Our shift_reg is stored as {byte1, byte2, byte3} (24 bits).
    assign out_bytes = shift_reg;

    // -------------------------------------------------
    // done pulse control
    // -------------------------------------------------
    // done is asserted in GET3 state. The spec says:
    // "signal the receipt of a message once all 3 bytes have been received
    //  (done). The FSM should signal done in the cycle immediately after the
    //  third byte of each message was successfully received."
    // 
    // Our current implementation asserts done while in GET3.
    // To match "the cycle immediately after the third byte was received",
    // we assert done one cycle after the third byte is latched.
    // We achieve this by using a registered done signal:
    //   - done is set in GET3 state.
    //   - In the next clock edge, done stays high for one cycle,
    //     then goes low in IDLE.
    // 
    // However, the waveform example shows done asserted high for the
    // entire cycle after the third byte (e.g., at 45ns done=1 while
    // out_bytes=2c8109 is present). This matches our registered done
    // approach if we keep done high for exactly one clock cycle.
    // 
    // To simplify, we assert done in GET3 and clear it in the
    // transition back to IDLE. Since out_bytes is driven from
    // shift_reg (which holds the valid message), out_bytes will be
    // valid whenever done is high.

endmodule

