module TopModule (
    input  logic clk,
    input  logic resetn,
    input  logic x,
    input  logic y,
    output logic f,
    output logic g
);

    // FSM state encoding (2 bits)
    typedef enum logic [1:0] {
        STATE_A   = 2'b00,
        STATE_B   = 2'b01,
        STATE_C   = 2'b10,
        STATE_D   = 2'b11
    } state_t;

    state_t state, next_state;

    //--------------------------------------------------------------------
    // State register (positive-edge triggered, active-low reset)
    //--------------------------------------------------------------------
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= STATE_A;
        end else begin
            state <= next_state;
        end
    end

    //--------------------------------------------------------------------
    // Shift‑register for the last two x values (sampled on each posedge)
    //--------------------------------------------------------------------
    logic [1:0] x_hist;

    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            x_hist <= 2'b00;
        end else begin
            x_hist <= {x_hist[0], x};
        end
    end

    //--------------------------------------------------------------------
    // Next‑state logic (combinational)
    //--------------------------------------------------------------------
    always_comb begin
        // Default next state is current state (no change)
        next_state = state;

        // Default outputs are 0 unless explicitly set below
        f     = 1'b0;
        g     = 1'b0;

        case (state)
            STATE_A: begin
                // As long as reset is asserted, stay in A and f=0, g=0
                // When reset is de‑asserted, go to STATE_B at the next clock edge
                if (!resetn) begin
                    next_state = STATE_B;
                end
            end

            STATE_B: begin
                // After reset de‑assertion, f is set to 1 for one clock cycle
                f = 1'b1;
                // Move to STATE_C to start monitoring x
                next_state = STATE_C;
            end

            STATE_C: begin
                // Monitor x for the sequence 1,0,1 over three successive cycles.
                // The shift register x_hist holds the last two sampled x values.
                // The current x is available as x.
                // Sequence 1,0,1 means:
                //   first cycle: x = 1
                //   second cycle: x = 0
                //   third cycle: x = 1
                // Using the histogram we can detect this pattern.
                if (x_hist == 2'b10 && x == 1'b1) begin
                    // Detected the final ‘1’ of the sequence 1,0,1
                    next_state = STATE_D;
                end
                // Otherwise remain in STATE_C
            end

            STATE_D: begin
                // g is set high when we enter STATE_D (on the clock edge that
                // transitions from STATE_C).  It will be kept or cleared in
                // the same STATE_D block on subsequent cycles.
                g = 1'b1;

                // Check y: if y becomes 1 within at most two clock cycles,
                // we stay in STATE_D (g stays 1 permanently).
                // If y does not become 1 within two cycles, g is set to 0
                // permanently (transition to STATE_E).
                if (y) begin
                    // y went high within the window – keep g=1 forever
                    next_state = STATE_D;
                end else begin
                    // y still low after two cycles – timeout
                    next_state = STATE_E;
                end
            end

            STATE_E: begin
                // g = 0 permanently until reset
                g = 1'b0;
                // Stay in ERROR state
                next_state = STATE_E;
            end

            default: next_state = STATE_A;
        endcase
    end

    //--------------------------------------------------------------------
    // Output assignments
    //--------------------------------------------------------------------
    // f is pulsed high for one cycle in STATE_B (already achieved by the
    // combinational assignment in that state).
    // g is driven from the STATE_D / STATE_E blocks above.

endmodule

