module TopModule (
    input  clk,
    input  reset,
    output ena   // 3 bits: enable for tens, hundreds, thousands
    output q     // 16 bits: BCD digits
);

    // Internal registers for the 4 BCD digits (ones, tens, hundreds, thousands)
    reg  [3:0] d0; // ones
    reg  [3:0] d1; // tens
    reg  [3:0] d2; // hundreds
    reg  [3:0] d3; // thousands

    // ena[0] is not used per specification (only upper three digits need enables)
    assign ena = {d3[3], d2[3], d1[3]}; // MSB of each digit indicates carry to next

    // BCD increment logic for one digit
    // next = (d + 1) if not at 9, else 0 with carry out
    wire [3:0] next_d0 = (d0 == 4'd9) ? 4'd0 : d0 + 1'b1;
    wire [3:0] next_d1 = (d1 == 4'd9) ? 4'd0 : d1 + ena[0]; // ena[0] is carry from d0
    wire [3:0] next_d2 = (d2 == 4'd9) ? 4'd0 : d2 + ena[1];
    wire [3:0] next_d3 = (d3 == 4'd9) ? 4'd0 : d3 + ena[2];

    // Actually, ena should be generated from the carry logic.
    // Let's re-define ena based on carry out of each digit.
    // carry_out_d0 = (d0 == 4'd9)
    // carry_out_d1 = (d1 == 4'd9) & carry_in_from_d0
    // etc.

    // Re-defining internal wires for carry propagation
    wire carry0;
    wire carry1;
    wire carry2;

    assign carry0 = (d0 == 4'd9);
    assign carry1 = (d1 == 4'd9) & carry0;
    assign carry2 = (d2 == 4'd9) & carry1;

    // ena outputs: enable for tens (d1), hundreds (d2), thousands (d3)
    // Typically ena[i] is high when the next digit should increment.
    // Here we map ena[0] -> tens, ena[1] -> hundreds, ena[2] -> thousands
    // Or as per spec: "output ena (3 bits)" indicating when each upper digit should increment.
    // We'll assign ena based on the carry into the next digit.
    // Actually, standard BCD counter ena means "count enable for this digit".
    // If we are counting continuously, ena might just be the carry from the lower digit.
    // Let's stick to: ena[0] = carry0 (enable tens to increment when ones rolls over)
    //              ena[1] = carry1 (enable hundreds)
    //              ena[2] = carry2 (enable thousands)
    // But the port ena is 3 bits. Usually, for a ripple enable, it's the carries.
    // Let's output the carries as ena.

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            d0 <= 4'd0;
            d1 <= 4'd0;
            d2 <= 4'd0;
            d3 <= 4'd0;
        end else begin
            d0 <= next_d0;
            // d1 increments if carry0 occurs, else holds
            d1 <= (carry0) ? ( (d1 == 4'd9) ? 4'd0 : d1 + 1'b1 ) : d1;
            d2 <= (carry1) ? ( (d2 == 4'd9) ? 4'd0 : d2 + 1'b1 ) : d2;
            d3 <= (carry2) ? ( (d3 == 4'd9) ? 4'd0 : d3 + 1'b1 ) : d3;
        end
    end

    // Assign output q concatenating the four digits
    assign q = {d3, d2, d1, d0};

    // Assign ena based on carries
    // ena[0] corresponds to tens enable (carry from ones)
    // ena[1] corresponds to hundreds enable
    // ena[2] corresponds to thousands enable
    assign ena = {carry2, carry1, carry0};

endmodule

