module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic x,
    output logic z
);

    // State register (3 bits, synchronous reset)
    logic [2:0] y;
    logic [2:0] next_y; // Next-state net

    // Next-state combinational logic
    always_comb begin
        case (y)
            3'b000: next_y = (x) ? 3'b001 : 3'b000;
            3'b001: next_y = (x) ? 3'b100 : 3'b001;
            3'b010: next_y = (x) ? 3'b001 : 3'b010;
            3'b011: next_y = (x) ? 3'b010 : 3'b001;
            3'b100: next_y = (x) ? 3'b100 : 3'b011;
            default:  next_y = 3'b000;
        endcase
    end

    // Output combinational logic
    always_comb begin
        case (y)
            3'b011, 3'b100: z = 1'b1;
            default:        z = 1'b0;
        endcase
    end

    // State register update (positive-edge triggered, synchronous reset)
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            y <= 3'b000;
        else
            y <= next_y;
    end

endmodule
